<script setup lang="ts">
import {ArrowLeft,ArrowUp,ArrowDown,X,Plus} from 'lucide-vue-next'
import type {LearningRoute} from '~/shared/routes'
definePageMeta({layout:'admin',key:route=>route.fullPath})
useHead({title:'编辑路线 — AttackBox'})
const id=String(useRoute().params.id),isNew=id==='new'
const {data:source}=await useFetch<{data:{id:string;title:string;status:string}[]}>('/api/admin/modules',{key:'admin:route-module-options'})
const title=ref(''),summary=ref(''),ids=ref<string[]>([]),version=ref(0),state=ref('unpublished'),notice=ref(''),busy=ref(false),loaded=ref(isNew),query=ref('')
if(!isNew){try{const r=await useRequestFetch()<{data:LearningRoute}>(`/api/admin/routes/${id}`);title.value=r.data.title;summary.value=r.data.summary;ids.value=r.data.modules!.map(m=>m.id);version.value=r.data.lockVersion;state.value=r.data.status;loaded.value=true}catch{notice.value='无法读取路线，请返回列表重试'}}
const selected=computed(()=>ids.value.map(id=>source.value?.data.find(m=>m.id===id)).filter(Boolean))
const options=computed(()=>source.value?.data.filter(m=>!ids.value.includes(m.id)&&m.title.toLowerCase().includes(query.value.toLowerCase()))||[])
function move(index:number,delta:number){const next=[...ids.value];[next[index],next[index+delta]]=[next[index+delta]!,next[index]!];ids.value=next}
async function save(intent:'draft'|'publish'){
 if(busy.value||!loaded.value)return
 busy.value=true;notice.value=''
 try{const r=await $fetch<{data:{id:string}}>(isNew?'/api/admin/routes':`/api/admin/routes/${id}`,{method:isNew?'POST':'PUT',body:{title:title.value,summary:summary.value,moduleIds:ids.value,lockVersion:version.value,intent}});await clearNuxtData('admin:routes');if(isNew)await navigateTo(`/admin/routes/${r.data.id}`);else{version.value++;state.value=intent==='publish'?'published':'unpublished';notice.value=intent==='publish'?'已保存并发布':'已保存为草稿'}}catch(e:any){notice.value=e?.data?.message||'保存失败'}finally{busy.value=false}
}
</script>
<template><div class="editor"><NuxtLink to="/admin/routes" class="back"><ArrowLeft :size="14"/>路线列表</NuxtLink><header><div><h1>{{isNew?'新建路线':'编辑路线'}}</h1><span class="muted">{{state==='published'?'已发布':'草稿'}}</span></div><div class="save-actions"><button :disabled="busy||!loaded" @click="save('draft')">保存为草稿</button><button class="primary" :disabled="busy||!loaded" @click="save('publish')">保存并发布</button></div></header><p v-if="notice" role="status" class="notice">{{notice}}</p><div v-if="loaded" class="grid"><section class="panel"><h2>路线信息</h2><label>名称 <span>*</span><input v-model="title" maxlength="160" placeholder="例如：Web 安全基础"/></label><label>简介<textarea v-model="summary" maxlength="500" rows="4" placeholder="说明这条路线适合谁、涵盖什么。"/></label><h2 class="outline-title">模块顺序 <small>{{ids.length}} / 100</small></h2><p v-if="!ids.length" class="muted">从右侧添加模块，再按学习顺序排列。</p><ol><li v-for="(item,index) in selected" :key="item!.id"><span class="number">{{String(index+1).padStart(2,'0')}}</span><div class="module-name">{{item!.title}}<small v-if="item!.status!=='published'">尚未发布</small></div><button :aria-label="`上移 ${item!.title}`" :disabled="index===0" @click="move(index,-1)"><ArrowUp :size="15"/></button><button :aria-label="`下移 ${item!.title}`" :disabled="index===ids.length-1" @click="move(index,1)"><ArrowDown :size="15"/></button><button :aria-label="`移除 ${item!.title}`" @click="ids.splice(index,1)"><X :size="15"/></button></li></ol></section><aside class="panel"><h2>添加模块</h2><input v-model="query" aria-label="搜索模块" placeholder="搜索模块名称"/><div class="choices"><button v-for="item in options" :key="item.id" :disabled="ids.length>=100" @click="ids.push(item.id)"><div>{{item.title}}<small>{{item.status==='published'?'已发布':'草稿，发布路线前需先发布模块'}}</small></div><Plus :size="16"/></button><p v-if="!options.length" class="muted">没有可添加的模块</p></div></aside></div></div></template>
<style scoped>
.editor{max-width:1400px;min-width:900px}header,header>div,.save-actions{display:flex;align-items:center;gap:16px}header{justify-content:space-between;margin:24px 0}h1{font-size:24px;margin:0}.back{display:inline-flex;gap:7px;align-items:center;color:var(--muted);font-size:12px}.muted,small{color:var(--muted);font-size:12px}.grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:24px}.panel{padding:24px;background:var(--paper);border:1px solid var(--line);border-radius:10px}h2{font-size:15px;margin:0 0 20px}label{display:block;font-size:13px;margin-bottom:22px}label span{color:var(--error-ink)}input,textarea{display:block;width:100%;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:6px;padding:10px 12px;margin-top:9px;font:inherit}button{display:inline-flex;align-items:center;justify-content:center;gap:9px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--ink);padding:8px 12px;cursor:pointer;font-size:12px}button:disabled{opacity:.4;cursor:default}.primary{background:var(--ink);color:var(--paper)}.outline-title{padding-top:24px;border-top:1px solid var(--line);display:flex;justify-content:space-between}ol{padding:0;list-style:none}li{display:flex;gap:9px;align-items:center;border-top:1px solid var(--line);padding:16px 0;font-size:13px}.number{color:var(--muted);width:30px}.module-name{flex:1}small{display:block;margin-top:5px}li button{padding:6px}.choices{max-height:600px;overflow:auto;margin-top:16px}.choices button{width:100%;text-align:left;justify-content:space-between;border:0;border-bottom:1px solid var(--line);border-radius:0;padding:15px 0}.notice{background:var(--soft);padding:14px;font-size:13px;border-radius:6px}
</style>
